#include <iostream>
using namespace std;

const int MOD = 1e9 + 7;

long long pow(long long a, long long b) {
    long long ans = 1;
    while (b > 0) {
        if (b & 1) ans = ans * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return ans;
}

int main() {
    long long a, b;
    cin >> a >> b;
    cout << pow(a, b) << endl;
    return 0;
}

#include <iostream>
using namespace std;

const int MOD = 1e9 + 7;
struct Matrix {
    long long m[2][2];
    Matrix() { m[0][0] = m[0][1] = m[1][0] = m[1][1] = 0; }
};

Matrix operator*(const Matrix& a, const Matrix& b) {
    Matrix c;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            for (int k = 0; k < 2; k++)
                c.m[i][j] = (c.m[i][j] + a.m[i][k] * b.m[k][j]) % MOD;
    return c;
}

Matrix pow(Matrix a, long long b) {
    Matrix ans;
    ans.m[0][0] = ans.m[1][1] = 1;
    while (b > 0) {
        if (b & 1) ans = ans * a;
        a = a * a;
        b >>= 1;
    }
    return ans;
}

int main() {
    long long n;
    cin >> n;
    Matrix a;
    a.m[0][0] = a.m[0][1] = a.m[1][0] = 1;
    Matrix res = pow(a, n);
    cout << res.m[0][0] << endl;
    return 0;
}

#include <iostream>
using namespace std;

const int MOD = 1e9 + 7;
int a[105][105], b[105][105], c[105][105];

int main() {
    int n, m, p;
    cin >> n >> m >> p;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) cin >> a[i][j];
    for (int i = 0; i < m; i++)
        for (int j = 0; j < p; j++) cin >> b[i][j];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < p; j++)
            for (int k = 0; k < m; k++)
                c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < p; j++) cout << c[i][j] << " ";
        cout << endl;
    }
    return 0;
}
